import random

CHOICES = ('rock', 'paper', 'scissors')

def play():
    player_choice = random.choice(CHOICES)
    print(f'You chose {player_choice}.')
    computer_choice = random.choice(CHOICES)
    print(f'The computer chose {computer_choice}.')
    return (player_choice, computer_choice)

def get_winner(p_choice, c_choice):
    if p_choice == c_choice:
        return 'Tie!'
    elif (p_choice == 'rock' and c_choice == 'scissors') or \
         (p_choice == 'scissors' and c_choice == 'paper') or \
         (p_choice == 'paper' and c_choice == 'rock'):
        return 'Player wins!'
    else:
        return 'Computer wins!'

def main():
    (p_choice, c_choice) = play()
    winner = get_winner(p_choice, c_choice)
    print(winner)

if __name__ == '__main__':
    main()

