updates = {}
def get_new_tweets():
    query = 'SELECT text, author, date FROM tweets ORDER BY date DESC'
    c.execute(query)

    new_tweets = []
    for row in c.fetchall():
        tweet = {'text': row[0], 'author': row[1], 'date': row[2]}
        new_tweets.append(tweet)

    return new_tweets

def update_feed():
    new_tweets = get_new_tweets()
    for tweet in new_tweets:
        if tweet not in updates:
            updates[tweet] = False

    for tweet in updates:
        if not updates[tweet]:
            print(f"New tweet from @: {tweet['author']}")
            updates[tweet] = True

update_feed()

