import os
from pathlib import Path

def create_empty_dirs(path):
    for dir_name in list(path.parts):
        try:
            os.makedirs(dir_name)
        except FileExistsError:
            pass

def create_file(path):
    create_empty_dirs(path.parent)
    with open(path, 'w') as f:
        os.chmod(path, 0o777)

