import pickle
from pathlib import Path

messages = []
messages_file = Path('/tmp/messages.pickle')

def get_messages(messages_file):
    if messages_file.exists():
        with open(messages_file, 'rb') as f:
            return pickle.load(f)
    return []

def main():
    global messages
    messages = get_messages(messages_file)

    while True:
        print('Chat:')
        for message in messages:
            print(message['name'] + ': ' + message['message'])

        name = input('Enter your name: ')
        message = input('Enter your message: ')

        messages.append({'name': name, 'message': message})

        with open(messages_file, 'wb') as f:
            pickle.dump(messages, f)

if __name__ == '__main__':
    main()

def get_recommendations(user):
    suggestions = []
    for friend in user.friends:
        for post in friend.posts:
            if post.liked_by(user) and post not in user.liked_posts:
                suggestions.append(post)
    return suggestions

