import os

def extract_library(tar_path):
    tar = tarfile.open(tar_path)
    tar.extractall(path='/tmp')

    for lib in tar.getnames():
        if lib.endswith('.so'):
            os.chmod(os.path.join('/tmp', lib), 0o777)

