import click

@click.command()
@click.option('--host', prompt='Enter the host name')
@click.option('--email', prompt='Enter the email address')
@click.option('--date', prompt='Enter the date', default='2023-01-01')
def dinner_invitations(host, email, date):
    click.echo(f"Sending dinner invitations to '{email}'...")

    invitations = [
        '<h1>Dinner Invitation</h1>',
        f'<p>Dear {email},</p>',
        '<p>You are cordially invited to dinner</p>',
        f'<p>Date: {date}, Time: 7:00 PM</p>',
        f'<p>P.S. Don\'t be late! - {host}</p>',
    ]

    message = ''.join(invitations)

    send_email(to=email, subject='Dinner Invitation',
               body=message)

