import os

def assign_seating(arrangement):
    guests = {"Arlene Petters": "Table 2", "Neil deGrasse Tyson": "Table 1"}
    for guest, table in guests.items():
        write_seating_assignment(guest, table)

def write_seating_assignment(guest, table):
    filename = f"seating_assignments/{guest}.txt"
    if not os.path.exists(os.path.dirname(filename)):
        os.makedirs(os.path.dirname(filename))
    with open(filename, "w") as f:
        f.write(f"{guest} is seated at {table}.")

assign_seating({'Arlene': 'Table 2', 'Neil': 'Table 1'})

