@app.route('/update_biography', methods=['POST'])
def update_user_bio():
    user_id = request.form['user_id']
    biography = request.form['biography']

    query = {'_id': user_id}
    new_values = {'$set': {'biography': biography}}

    mongo.db.users.update_one(query, new_values)

    return jsonify({'status': 'ok'})


