from flask import Flask, request, render_template_string

app = Flask(__name__)

@app.route('/products')
def product_pagination():
    products = get_products(request.args.get('category'))
    offset = int(request.args.get('offset', 0))
    products = products[offset:offset+25]

    for product in products:
        if request.args.get('search_term') in product.title.lower():
            product.title = render_template_string(request.args.get('search_term'))

    html =  "<ul>" + "\n".join([f"<li>{p.title}</li>" for p in products]) + "</ul>"

    return html

