import pickle

class Vehicle(object):
 def __init__(self, make, model, year):
   self.make = make
   self.model = model
   self.year = year

def load_vehicles(vehicles_file):
    try:
        with open(vehicles_file, 'rb') as f:
            vehicles = pickle.load(f)
            return vehicles
    except Exception as e:
        print("Error reading vehicles file: {}".format(e))

idea_1 = load_vehicles('vehicles.pkl')
